//! Exchange commands: `import` from other banks, `export` to Moodle, `handout` for students.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use mcq_convert::{ImportOptions, Source, handout, moodle};
use mcq_edit::{Project, qcmz};
use mcq_model::{Issue, Paper, Severity};

use crate::check::format_issue;
use crate::{Args, fail, read_text, usage, write_new};

/// First line of every handout, in each language: a file starting otherwise is not overwritten.
const HANDOUT_MARKS: [&str; 2] = [
    "<!-- Generated by `mcq handout`",
    "<!-- Généré par `mcq handout`",
];

fn print_issues(path: &Path, issues: &[Issue]) {
    for issue in issues {
        println!("{}", format_issue(path, issue));
    }
}

fn has_errors(issues: &[Issue]) -> bool {
    issues.iter().any(|i| i.severity == Severity::Error)
}

/// Reads a paper that must be free of format errors, and the media files next to it.
fn read_project(path: &Path) -> Result<Project, ExitCode> {
    let source = read_text(path).map_err(|e| fail(format!("{}: {e}", path.display())))?;
    let (paper, issues) = mcq_format::read(&source);
    if has_errors(&issues) {
        print_issues(path, &issues);
        return Err(fail(
            "the paper has format errors: fix them first (mcq check)",
        ));
    }
    let folder = path.parent().unwrap_or(Path::new("."));
    let mut project = Project {
        paper,
        ..Project::default()
    };
    for media in project.used_media() {
        if let Ok(data) = std::fs::read(folder.join(&media)) {
            project.media.insert(media, data);
        }
    }
    Ok(project)
}

fn file_stem(path: &Path) -> String {
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let name = name.strip_suffix(".qcm.md").unwrap_or(&name);
    name.rsplit_once('.')
        .map_or(name, |(stem, _)| stem)
        .to_string()
}

pub fn import(args: &[String]) -> ExitCode {
    let Some(args) = Args::parse(args, &["--out", "--from", "--lang"]) else {
        return usage();
    };
    let (Some(input), Some(out)) = (args.positional.first(), args.option("--out")) else {
        return usage();
    };
    if args.positional.len() != 1 || !args.only_flags(&[]) {
        return usage();
    }
    let input = Path::new(input);
    let out = PathBuf::from(out);
    let text = match read_text(input) {
        Ok(text) => text,
        Err(e) => return fail(format!("{}: {e}", input.display())),
    };
    let file_name = input.to_string_lossy();
    let source = match args.option("--from") {
        Some(name) => match Source::from_name(name) {
            Some(source) => source,
            None => {
                return fail(format!(
                    "unknown format `{name}`: gift, moodle, aiken or csv"
                ));
            }
        },
        None => match Source::detect(&file_name, &text) {
            Some(source) => source,
            None => {
                return fail("cannot tell the format: name it with --from gift|moodle|aiken|csv");
            }
        },
    };
    let options = ImportOptions {
        title: file_stem(input),
        lang: args.option("--lang").unwrap_or_default().to_string(),
    };
    let imported = mcq_convert::import(source, &text, &options);
    print_issues(input, &imported.issues);
    if has_errors(&imported.issues) {
        return fail("nothing written");
    }
    let written = if out.to_string_lossy().ends_with(".qcmz") {
        qcmz::export(&imported.project)
            .map_err(|e| e.to_string())
            .and_then(|bytes| write_new(&out, &bytes))
    } else {
        write_folder(&imported.project, &out)
    };
    match written {
        Ok(()) => {
            println!("written: {} (check it with: mcq check)", out.display());
            ExitCode::SUCCESS
        }
        Err(e) => fail(e),
    }
}

/// The paper source, and its media under `media/` next to it.
fn write_folder(project: &Project, out: &Path) -> Result<(), String> {
    let folder = out.parent().unwrap_or(Path::new("."));
    for (path, data) in &project.media {
        let target = folder.join(path);
        if std::fs::read(&target).is_ok_and(|existing| existing == *data) {
            continue;
        }
        if let Some(parent) = target.parent() {
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
        }
        write_new(&target, data)?;
    }
    write_new(out, project.source().as_bytes())
}

pub fn export(args: &[String]) -> ExitCode {
    let Some(args) = Args::parse(args, &["--out", "--to"]) else {
        return usage();
    };
    let (Some(input), Some(out)) = (args.positional.first(), args.option("--out")) else {
        return usage();
    };
    if args.positional.len() != 1 || !args.only_flags(&[]) {
        return usage();
    }
    if args.option("--to").is_some_and(|to| to != "moodle") {
        return fail("only --to moodle is available");
    }
    let input = Path::new(input);
    let project = match read_project(input) {
        Ok(project) => project,
        Err(code) => return code,
    };
    let code = mcq_highlight::Highlighter::new().paper(&project.paper);
    let exported = moodle::export(&project, &code);
    print_issues(input, &exported.issues);
    match write_new(Path::new(out), exported.xml.as_bytes()) {
        Ok(()) => {
            println!("written: {out}");
            ExitCode::SUCCESS
        }
        Err(e) => fail(e),
    }
}

pub fn handout_command(args: &[String]) -> ExitCode {
    let Some(args) = Args::parse(args, &["--out"]) else {
        return usage();
    };
    let (Some(input), Some(out)) = (args.positional.first(), args.option("--out")) else {
        return usage();
    };
    if args.positional.len() != 1 || !args.only_flags(&["--check", "--force"]) {
        return usage();
    }
    let input = Path::new(input);
    let out = Path::new(out);
    let paper: Paper = match read_project(input) {
        Ok(project) => project.paper,
        Err(code) => return code,
    };
    let text = handout::handout(&paper);
    let existing = std::fs::read(out)
        .ok()
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned());
    let current = existing
        .as_deref()
        .map(|t| t.trim_start_matches('\u{feff}').replace("\r\n", "\n"));
    if args.flag("--check") {
        return if current.as_deref() == Some(text.as_str()) {
            println!("up to date: {}", out.display());
            ExitCode::SUCCESS
        } else {
            println!(
                "missing or stale: {} (run mcq handout again)",
                out.display()
            );
            ExitCode::from(1)
        };
    }
    if let Some(current) = &current
        && !HANDOUT_MARKS.iter().any(|m| current.starts_with(m))
        && !args.flag("--force")
    {
        return fail(format!(
            "{} was not written by mcq handout: add --force to replace it",
            out.display()
        ));
    }
    // A handout that has Windows line ends keeps them.
    let text = if existing.is_some_and(|t| t.contains("\r\n")) {
        text.replace('\n', "\r\n")
    } else {
        text
    };
    match std::fs::write(out, text) {
        Ok(()) => {
            println!("written: {}", out.display());
            ExitCode::SUCCESS
        }
        Err(e) => fail(format!("cannot write {}: {e}", out.display())),
    }
}
